import org.joda.time.format.DateTimeFormatter;
import org.joda.time.format.ISODateTimeFormat;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class LocalDateTime_fromCalendarFields_TriageGen2Test {

    @Test
    public void testFromCalendarFields_ValidCalendar() {
        // Setup a specific date and time in Calendar
        // Note: Calendar.MONTH is 0-based, so January is 0.
        Calendar calendar = new GregorianCalendar();
        calendar.set(2023, Calendar.OCTOBER, 25, 14, 30, 45);
        calendar.set(Calendar.MILLISECOND, 123);
        calendar.set(Calendar.AM_PM, Calendar.PM);

        // Expected: Joda LocalDateTime uses 1-based months
        LocalDateTime expected = new LocalDateTime(2023, 11, 25, 14, 30, 45, 123);
        LocalDateTime actual = LocalDateTime.fromCalendarFields(calendar);

        assertEquals("The LocalDateTime should match the values provided by the Calendar", expected, actual);
    }






}

