public class LocalDateTime_fromCalendarFields_TriageGen2Test {





    @Test
    public void testFromCalendarFields_BoundaryValues() {
        // Testing boundary values for time components
        Calendar calendar = new GregorianCalendar();
        calendar.set(2000, Calendar.DECEMBER, 31, 23, 59, 59);
        calendar.set(Calendar.MILLISECOND, 999);

        LocalDateTime expected = new LocalDateTime(2000, 12, 31, 23, 59, 59, 999);
        LocalDateTime actual = LocalDateTime.fromCalendarFields(calendar);

        assertEquals("Should handle end of year/day boundary values correctly", expected, actual);
    }


